
import { mapMediaPipeToCanonical } from "@motion-forge/pose";

export const LOW_CONFIDENCE_FLOOR = 0.25;

export class PosePipeline {
  constructor(onPose, onError) {
    this.worker = null;
    this.isProcessing = false;
    this.isWorkerReady = false;
    this.videoEl = null;
    this.animId = 0;
    this.callback = onPose || null;
    this.onErrorCallback = onError || null;
    this.frameCount = 0;
    this.lastFpsTimestamp = performance.now();
    this.currentFps = 0;
    this.skippedLowConfidenceFrames = 0;
    this.started = false;
    this.errorBuffer = [];
    this.flushErrorTimer = 0;
  }

  start(video, providerId = "mediapipe") {
    this.videoEl = video;
    this.skippedLowConfidenceFrames = 0;
    this.started = true;
    this.initWorker(providerId);
    if (!this.animId) {
      this.loop();
    }
  }

  stop() {
    this.started = false;
    if (this.animId) {
      cancelAnimationFrame(this.animId);
      this.animId = 0;
    }
    this.videoEl = null;
    try {
      if (this.worker) {
        this.worker.postMessage({ type: "DISPOSE" });
        try { this.worker.terminate(); } catch (e) {}
        this.worker = null;
      }
    } finally {
      this.isWorkerReady = false;
      this.isProcessing = false;
      this.errorBuffer.length = 0;
    }
  }

  initWorker(providerId) {
    if (this.worker) return;
    this.worker = new Worker(new URL("./pose.worker.js", import.meta.url), { type: "module" });
    this.worker.onmessage = (e) => {
      const { type, payload, error } = e.data;
      if (type === "INIT_SUCCESS") {
        this.isWorkerReady = true;
        this.errorBuffer.length = 0;
      } else if (type === "INIT_ERROR") {
        this.isWorkerReady = false;
        const msg = error || "Nao foi possivel inicializar a informacao na web. Tente parar e abrir a camera novamente.";
        this.bufferError(msg);
        this.onErrorCallback?.(msg);
      } else if (type === "PROVIDER_UNAVAILABLE") {
        this.isWorkerReady = false;
        this.isProcessing = false;
        const msg = payload?.providerId === "mediapipe"
          ? "Backend selecionado nao esta disponivel."
          : "Backend nao disponivel na web neste MVP - informacao desativada.";
        this.bufferError(msg);
        this.onErrorCallback?.(msg);
      } else if (type === "POSE_RESULT") {
        this.isProcessing = false;
        this.updateFps();
        const result = payload;
        if (result?.canonical && result.canonical.overallConfidence < LOW_CONFIDENCE_FLOOR) {
          this.skippedLowConfidenceFrames++;
          return;
        }
        this.callback?.(result, this.currentFps, result.latencyMs);
      } else if (type === "NO_POSE") {
        this.isProcessing = false;
        this.updateFps();
        this.callback?.(null, this.currentFps, payload?.latencyMs ?? 0);
      } else if (type === "FRAME_ERROR") {
        this.isProcessing = false;
        const msg = error || "Falha em um frame de pose. A captura continua.";
        this.bufferError(msg);
      }
    };
    this.worker.postMessage({ type: "INIT", payload: { providerId } });
  }

  updateFps() {
    this.frameCount++;
    const now = performance.now();
    const elapsed = now - this.lastFpsTimestamp;
    if (elapsed >= 1000) {
      this.currentFps = Math.round((this.frameCount * 1000) / elapsed);
      this.frameCount = 0;
      this.lastFpsTimestamp = now;
    }
  }

  loop = async () => {
    this.animId = requestAnimationFrame(this.loop);
    if (!this.started) return;
    if (!this.videoEl || !this.worker || !this.isWorkerReady || this.isProcessing ||
        this.videoEl.readyState < 2 || this.videoEl.paused || this.videoEl.videoWidth === 0) {
      return;
    }
    try {
      this.isProcessing = true;
      const timestamp = performance.now();
      const bitmap = await createImageBitmap(this.videoEl);
      this.worker.postMessage({ type: "PROCESS_FRAME", payload: { imageBitmap: bitmap, timestamp } }, [bitmap]);
    } catch (e) {
      this.isProcessing = false;
    }
  };

  bufferError(message) {
    if (message && !this.errorBuffer.includes(message)) {
      this.errorBuffer.push(message);
      if (this.errorBuffer.length > 3) this.errorBuffer.shift();
    }
    if (!this.flushErrorTimer) {
      this.flushErrorTimer = window.setTimeout(() => {
        this.flushErrorTimer = 0;
        if (!this.started || this.errorBuffer.length === 0) return;
        const latest = this.errorBuffer[this.errorBuffer.length - 1];
        if (latest) this.onErrorCallback?.(latest);
      }, 800);
    }
  }
}
